def goal(kind, path="", value=None, label="", **kwargs):
    return {"kind": kind, "path": path, "value": value, "label": label, **kwargs}


def directory(path):
    return "install -d -o learner -g archive {}\n".format(shlex.quote(path))


def write(path, text, mode="644", owner="learner:archive"):
    return (directory(path.rsplit("/", 1)[0]) +
        "printf %s {} > {}\nchmod {} {}\nchown {} {}\n".format(shlex.quote(text), shlex.quote(path),
        mode, shlex.quote(path), owner, shlex.quote(path)))


def worker(name):
    return ("runuser -u learner -- sh -c " + shlex.quote(
        f"nohup sleep 86400 >/dev/null 2>&1 & echo $! > /srv/archive/{name}.pid") + "\n")


def theory(mid, chapter, title, topics, story, boss=False, clue=""):
    return Mission(mid, chapter, title, story, tuple(topics),
        "브리핑을 읽고 상황에 맞는 판단을 선택하세요.", kind="scenario", boss=boss,
        hints=("브리핑의 역할과 용어를 구분하세요.", "quest lesson으로 해당 개념을 다시 확인할 수 있습니다.",
               "각 선택지를 브리핑의 정의와 비교하세요. 정답 해설은 답변 뒤 제공됩니다."),
        debrief="장치·설치·GUI 등 실제 조작하지 않은 내용은 상황 판단 결과입니다.", clue=clue)


